def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    highest_prev_bid = None
    aggressive_count = 0
    desperate_opp = 0
    for opp in alive_opponents:
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            desperate_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if isinstance(bid, (int, float)):
            if highest_prev_bid is None or bid > highest_prev_bid:
                highest_prev_bid = bid
            if bid >= DAILY_SALARY * 0.8:
                aggressive_count += 1

    units = supply / float(WATER_REQ)

    if hp <= 2:
        base = DAILY_SALARY * 0.95
    elif no_water >= 2:
        base = DAILY_SALARY * 0.88
    elif no_water == 1:
        base = DAILY_SALARY * 0.72
    else:
        if units >= 1.8:
            base = DAILY_SALARY * 0.34
        elif units >= 1.45:
            base = DAILY_SALARY * 0.46
        else:
            base = DAILY_SALARY * 0.62

    if highest_prev_bid is not None:
        if hp <= 3 or no_water >= 1:
            target = highest_prev_bid + 2.0
            if target > base:
                base = target
        elif highest_prev_bid >= DAILY_SALARY * 0.9:
            base = min(base, DAILY_SALARY * 0.4)
        else:
            target = highest_prev_bid + 1.0
            if target > base:
                base = target

    if aggressive_count >= 2 and hp > 3 and no_water == 0:
        base = min(base, DAILY_SALARY * 0.38)

    if desperate_opp >= 2 and hp <= 4:
        base = max(base, DAILY_SALARY * 0.8)

    if not alive_opponents:
        base = DAILY_SALARY * 0.25

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0
    return bid

