def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_agents = len(alive_opponents) + 1

    # Calculate a fair share bid
    fair_bid = DAILY_SALARY * 0.4

    # If HP is critical, bid more aggressively
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    # Check yesterday's competition
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If supply is tight, be more aggressive
        if supply < 18:
            return min(my_status['budget'], max(fair_bid, max_prev + 5))
        return min(my_status['budget'], max(fair_bid, max_prev * 0.9))

    return min(my_status['budget'], fair_bid)
